export const AUTH_HTTP_ERROR = 'AUTH_HTTP_ERROR'


export function authHttpError(authHttpError) {
  return {
    type: AUTH_HTTP_ERROR,
    authHttpError: authHttpError
  }
}

export function fetchAuth() {
  console.log('fetch auth');
  return dispatch => {
    //dispatch(requestAuth())
    return fetch('https://scbm.amfdev.co.uk/api/auth/', {
      method: "GET",
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Cache': 'no-cache'
      },
      credentials: 'include'
      })
      .then(async response => catchAuthHttpError(response, dispatch))
      .then(async response => catchAuthErrorMessage(response, dispatch))
      //.then(catchAuthResult)
      //.then(catchAuthInvalidCookies)
      //.then(doAuthSuccess)
      .catch(error => console.log(error));
  }

}

// Handle HTTP errors since fetch won't.
async function catchAuthHttpError(response, dispatch) {
  await console.log('catchAuthHttpError')
  if (!response.ok) {
    await dispatch(authHttpError(response.statusText))
    throw Error(response.statusText);
  }
  return await response;
}


// Handle HTTP errors since fetch won't.
async function catchAuthErrorMessage(response, dispatch) {
  await console.log('catchAuthErrorMessage')
    //if (jsonResponse.errorMessage) {
        
    //}
    await console.log(response)
  return await response;
}


